function getCellPosition(row, column) {
  if (!isInBoard(row, column)) return null;
  const rect = grid.getBoundingClientRect();
  return {
    x: rect.left + rect.width * (column + 0.5) / COLUMNS,
    y: rect.top + rect.height * (row + 0.5) / ROWS
  };
}
function screenToBoard(screenX, screenY) {
  const rect = grid.getBoundingClientRect();
  if (screenX < rect.left || screenY < rect.top || screenX >= rect.right || screenY >= rect.bottom) return null;
  const column = Math.floor((screenX - rect.left) / rect.width * COLUMNS);
  const row = Math.floor((screenY - rect.top) / rect.height * ROWS);
  return isInBoard(row, column) ? { row, column } : null;
}

