function getCellPosition(row, column) {
  if (!isInBoard(row, column)) return null;
  const rect = cells[row * COLUMNS + column].getBoundingClientRect();
  const sceneRect = document.querySelector(".scene").getBoundingClientRect();
  return {
    x: rect.left + rect.width / 2 - sceneRect.left,
    y: rect.top + rect.height / 2 - sceneRect.top
  };
}
function screenToBoard(screenX, screenY) {
  for (let row = 0; row < ROWS; row++) {
    for (let column = 0; column < COLUMNS; column++) {
      const rect = cells[row * COLUMNS + column].getBoundingClientRect();
      if (screenX >= rect.left && screenX < rect.right && screenY >= rect.top && screenY < rect.bottom) return { row, column };
    }
  }
  return null;
}

